String socialTime(dynamic raw){final d=DateTime.tryParse(raw?.toString()??'')?.toLocal();if(d==null)return '';final n=DateTime.now();if(n.difference(d).inDays==0)return '${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';if(n.difference(d).inDays<7)return ['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'][d.weekday-1];return '${d.day}.${d.month}.${d.year.toString().substring(2)}';}

class EnhancedMessagesScreen extends StatefulWidget{const EnhancedMessagesScreen({super.key});@override State<EnhancedMessagesScreen> createState()=>_EnhancedMessagesScreenState();}
class _EnhancedMessagesScreenState extends State<EnhancedMessagesScreen>{late Future<List<Map<String,dynamic>>> future;@override void initState(){super.initState();future=_load();}Future<List<Map<String,dynamic>>> _load()async{final b=OpenBackend.instance,me=b.userId,matches=await b.activeMatches(),out=<Map<String,dynamic>>[];for(final m in matches){final other=m['user_a']==me?m['user_b']:m['user_a'];final p=await b.client.from('profiles').select('id,display_name,avatar_url,city,is_online').eq('id',other).maybeSingle();final last=await b.lastMessage(m['id'].toString());final unread=await b.unreadForMatch(m['id'].toString());out.add({...m,'other_profile':p,'last':last,'unread':unread});}out.sort((a,b){final ad=DateTime.tryParse((a['last']?['created_at']??a['created_at']).toString())??DateTime(2000),bd=DateTime.tryParse((b['last']?['created_at']??b['created_at']).toString())??DateTime(2000);return bd.compareTo(ad);});return out;}void reload(){final next=_load();if(mounted)setState(()=>future=next);}@override Widget build(BuildContext context)=>SafeArea(child:Padding(padding:const EdgeInsets.fromLTRB(20,20,20,4),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Expanded(child:ui.PageTitle('Mesajlar','Eşleştiğin kişilerle konuş.')),IconButton(onPressed:reload,icon:const Icon(Icons.refresh_rounded))]),const SizedBox(height:18),Expanded(child:FutureBuilder<List<Map<String,dynamic>>>(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return _Empty('Mesajlar yüklenemedi','${s.error}',reload);final items=s.data??[];if(items.isEmpty)return _Empty('Henüz eşleşme yok.','Bir anahtar kabul edildiğinde sohbet burada açılacak.',reload);return ListView.separated(itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(_,i){final m=items[i],p=m['other_profile'] is Map?Map<String,dynamic>.from(m['other_profile']):<String,dynamic>{},last=m['last'] is Map?Map<String,dynamic>.from(m['last']):<String,dynamic>{},unread=(m['unread'] as num?)?.toInt()??0,avatar=p['avatar_url']?.toString(),has=avatar!=null&&avatar.isNotEmpty;return InkWell(onTap:()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>EnhancedChatScreen(matchId:m['id'].toString(),profile:p)));if(mounted)reload();},borderRadius:BorderRadius.circular(24),child:Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:ui.OpenApp.soft,borderRadius:BorderRadius.circular(24)),child:Row(children:[Stack(children:[CircleAvatar(radius:28,backgroundColor:Colors.white,backgroundImage:has?NetworkImage(avatar):null,child:has?null:const Icon(Icons.person_rounded)),if(p['is_online']==true)Positioned(right:1,bottom:1,child:Container(width:13,height:13,decoration:BoxDecoration(color:ui.OpenApp.lime,shape:BoxShape.circle,border:Border.all(color:Colors.white,width:2))))]),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text((p['display_name']??'Open kullanıcısı').toString(),style:const TextStyle(fontSize:17,fontWeight:FontWeight.w900)),const SizedBox(height:4),Text(last.isEmpty?'Yeni eşleşme':(last['body']??'').toString(),maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:unread>0?ui.OpenApp.ink:ui.OpenApp.muted,fontWeight:unread>0?FontWeight.w800:FontWeight.w500))])),Column(crossAxisAlignment:CrossAxisAlignment.end,children:[Text(socialTime(last['created_at']??m['created_at']),style:const TextStyle(fontSize:11,color:ui.OpenApp.muted)),const SizedBox(height:7),if(unread>0)Container(constraints:const BoxConstraints(minWidth:22,minHeight:22),padding:const EdgeInsets.symmetric(horizontal:6),decoration:const BoxDecoration(color:ui.OpenApp.lime,shape:BoxShape.circle),alignment:Alignment.center,child:Text(unread>99?'99+':'$unread',style:const TextStyle(fontSize:11,fontWeight:FontWeight.w900)))])])));});}))])));}

class EnhancedChatScreen extends StatefulWidget{const EnhancedChatScreen({super.key,required this.matchId,required this.profile});final String matchId;final Map<String,dynamic> profile;@override State<EnhancedChatScreen> createState()=>_EnhancedChatScreenState();}
class _EnhancedChatScreenState extends State<EnhancedChatScreen>{final input=TextEditingController(),scroll=ScrollController();bool busy=false;String? failed;@override void initState(){super.initState();_read();}@override void dispose(){input.dispose();scroll.dispose();super.dispose();}Future<void> _read()async{try{await OpenBackend.instance.markMessagesRead(widget.matchId);}catch(_){}}void _bottom(){WidgetsBinding.instance.addPostFrameCallback((_){if(scroll.hasClients)scroll.animateTo(scroll.position.maxScrollExtent,duration:const Duration(milliseconds:220),curve:Curves.easeOut);});}Future<void> send([String? retry])async{final text=(retry??input.text).trim();if(text.isEmpty||busy)return;if(retry==null)input.clear();setState((){busy=true;failed=null;});try{await OpenBackend.instance.sendMessage(widget.matchId,text);_bottom();}catch(_){if(mounted)setState(()=>failed=text);}finally{if(mounted)setState(()=>busy=false);}}Future<void> _action(String value)async{final id=widget.profile['id']?.toString();if(id==null)return;if(value=='unmatch'){final ok=await _confirm('Eşleşmeyi kaldır','Bu sohbet kapanacak.');if(ok){await OpenBackend.instance.unmatch(widget.matchId);if(mounted)Navigator.pop(context);}}else if(value=='block'){final ok=await _confirm('Kullanıcıyı engelle','Eşleşme kaldırılacak ve bu kişiyi keşfette görmeyeceksin.');if(ok){await OpenBackend.instance.blockUser(id);if(mounted)Navigator.pop(context);}}else if(value=='report'){final reason=await showDialog<String>(context:context,builder:(c)=>SimpleDialog(title:const Text('Şikâyet nedeni'),children:['Uygunsuz davranış','Sahte profil','Taciz / spam','Diğer'].map((x)=>SimpleDialogOption(onPressed:()=>Navigator.pop(c,x),child:Padding(padding:const EdgeInsets.all(8),child:Text(x)))).toList()));if(reason!=null){await OpenBackend.instance.reportUser(id,reason,matchId:widget.matchId);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Şikâyetin alındı.')));}}}Future<bool> _confirm(String title,String text)async=>await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(title),content:Text(text),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Onayla'))]))??false;@override Widget build(BuildContext context){final name=(widget.profile['display_name']??'Open kullanıcısı').toString(),me=OpenBackend.instance.userId;return Scaffold(backgroundColor:Colors.white,appBar:AppBar(backgroundColor:Colors.white,title:Text(name,style:const TextStyle(fontWeight:FontWeight.w900)),actions:[PopupMenuButton<String>(onSelected:_action,itemBuilder:(_)=>const [PopupMenuItem(value:'unmatch',child:Text('Eşleşmeyi kaldır')),PopupMenuItem(value:'block',child:Text('Engelle')),PopupMenuItem(value:'report',child:Text('Şikâyet et'))])]),body:SafeArea(child:Column(children:[Expanded(child:StreamBuilder<List<Map<String,dynamic>>>(stream:OpenBackend.instance.messageStream(widget.matchId),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final msgs=[...s.data!]..sort((a,b)=>(a['created_at']??'').toString().compareTo((b['created_at']??'').toString()));_read();_bottom();if(msgs.isEmpty)return const Center(child:Text('İlk mesajı sen gönder ✨',style:TextStyle(color:ui.OpenApp.muted)));return ListView.builder(controller:scroll,padding:const EdgeInsets.all(18),itemCount:msgs.length,itemBuilder:(_,i){final m=msgs[i],mine=m['sender_id']==me;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:300),margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.symmetric(horizontal:15,vertical:10),decoration:BoxDecoration(color:mine?ui.OpenApp.lime:ui.OpenApp.soft,borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[Align(alignment:Alignment.centerLeft,child:Text((m['body']??'').toString())),const SizedBox(height:3),Row(mainAxisSize:MainAxisSize.min,children:[Text(socialTime(m['created_at']),style:TextStyle(fontSize:10,color:ui.OpenApp.ink.withValues(alpha:.55))),if(mine)...[const SizedBox(width:4),Icon(m['read_at']!=null?Icons.done_all_rounded:Icons.done_rounded,size:13,color:ui.OpenApp.ink.withValues(alpha:.55))]])])));});})),if(failed!=null)Container(margin:const EdgeInsets.fromLTRB(14,0,14,6),padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:ui.OpenApp.soft,borderRadius:BorderRadius.circular(14)),child:Row(children:[const Icon(Icons.error_outline_rounded,size:18),const SizedBox(width:8),const Expanded(child:Text('Mesaj gönderilemedi.')),TextButton(onPressed:()=>send(failed),child:const Text('Tekrar dene'))])),Padding(padding:const EdgeInsets.fromLTRB(14,8,14,14),child:Row(children:[Expanded(child:TextField(controller:input,textInputAction:TextInputAction.send,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Mesaj yaz...'))),const SizedBox(width:8),IconButton.filled(onPressed:busy?null:send,style:IconButton.styleFrom(backgroundColor:ui.OpenApp.lime,foregroundColor:ui.OpenApp.ink),icon:const Icon(Icons.arrow_upward_rounded))]))])));}}

